from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    anchor=max(others,key=lambda c:sum(r.count(c) for r in g))
    marker=[c for c in others if c!=anchor][0]
    # vertical segments of anchor color
    cols={}
    for c in range(W):
        rows=[r for r in range(H) if g[r][c]==anchor]
        if len(rows)>=2: cols[c]=rows
    # two segments: S1 starts at row0
    segs=[(c,rows) for c,rows in cols.items()]
    segs.sort(key=lambda x:x[1][0])
    (c1,r1),(c2,r2)=segs[0],segs[1]
    out=[row[:] for row in g]
    # region L: side of c1 with more space
    if c1>=W-1-c1: Lcols=range(0,c1)   # left of S1
    else: Lcols=range(c1+1,W)
    if c2>=W-1-c2: Rcols=range(0,c2)
    else: Rcols=range(c2+1,W)
    Rstart=min(r2)
    for r in range(H):
        for c in range(W):
            if g[r][c]==marker:
                out[r][c]=4
                # ray toward divider c2
                step=1 if c2>c else -1
                c=c
                cc=c+step
                while cc!=c2:
                    out[r][cc]=marker; cc+=step
    for r in r1:
        pass
    # projection: markers in R rows (rows of segment2) minus offset0
    for r in range(H):
        for c in range(W):
            if g[r][c]==marker and r in set(r2):
                off=r-Rstart
                if off==0: continue
                Lr=r-len(r1)
                if 0<=Lr<H:
                    for cc in Lcols: out[Lr][cc]=marker
    return out

